source("pre.R")
z <- zutable(t = as.POSIXct("2020-06-01 12:00:00", tz = "Asia/Tokyo"), u = as.POSIXct("2020-06-01 03:00:00", tz = "UTC"))
print(try_(nrow(z[t < Sys.time()]))); print(try_(nrow(z[u < Sys.time()]))); print(try_(nrow(z[t > as.POSIXct("2020-06-01 02:59:59", tz = "UTC")]))); print(try_(as.data.frame(z[select = .(e = t == u, l = t < u)])))
print(as.data.frame(z[select = .(s = cast(t, string), d = cast(t, date), h = date_trunc("hour", t), y = year(t), dd = day(t), nz = cast(cast(t, timestamp("us")), string), c = t == "2020-06-01 12:00:00")]))
z2 <- zutable(t = as.POSIXct("2020-06-01 23:30:00", tz = "Asia/Tokyo"), d = as.Date("2020-06-01")); print(try_(as.data.frame(z2[select = .(c = cast(t, date) == d, e = cast(d, timestamp("us", "Asia/Tokyo")) < t)]))); print(try_(z2[t > d])); print(try_(z2[t > "2020-06-01"]))
cat("--- conform/as_zutable\n")
df <- data.frame(a = 1:2, b = c("x", "y"))
print(try_(conform(df, schema(a = int32)))); print(try_(conform(df, schema(b = string, a = int32)))); print(try_(conform(df, schema(a = float64, b = string)))); print(try_(conform(df, schema(a = int32, b = enum(c("x", "y")))))); print(try_(conform(df, "a"))); print(try_(conform(list(a = 1), schema(a = float64)))); print(try_(conform(as_zutable(df), schema(a = not_null(int32), b = string, .metadata = c(k = "v"))))); print(metadata(conform(as_zutable(df), schema(a = not_null(int32), b = string, .metadata = c(k = "v")))))
print(try_(as_zutable(df, schema = "x"))); print(try_(as_zutable(list(a = 1:2, b = "x"), schema(a = int32, b = string)))); print(try_(as_zutable(df, schema(df)))); print(identical(as_zutable(as_zutable(df)), as_zutable(df)))
dn <- data.frame(a = 1:2); attr(dn$a, "label") <- "my label"; zz <- as_zutable(dn); print(attributes(zz$a)); print(attributes(zz[a > 0]$a)); print(attributes(zz[select = .(a)]$a)); print(attributes(zz[order = a]$a)); print(attributes(rbind(zz, zz)$a))
tb <- structure(list(a = 1:2), class = c("tbl_df", "tbl", "data.frame"), row.names = 1:2); print(class(as_zutable(tb)))
